    "Chaque chargement coûte 100 unités du minerai choisi. Changer de minerai remplace le stock en cours. Le chargement se fait dans la fenêtre Raffinage (onglet Upgrade) ou automatiquement (Soute du BOT).": "Cada carga cuesta 100 unidades del mineral elegido. Cambiar de mineral sustituye el stock actual. La carga se hace en la ventana Refinado (pestaña Upgrade) o automáticamente (Bodega del BOT).",
