    "L'énergie vient des bonus-box et du palladium (10 palladium = 1 énergie).": "La energía viene de las bonus box y del paladio (10 paladio = 1 energía).",
    "L'onglet Comparateur de la fenêtre Modules te dit quoi monter selon ton vaisseau et ton style (PvE / PvP, XP / honneur).": "La pestaña Comparador de la ventana Módulos te dice qué montar según tu nave y tu estilo (PvE / PvP, XP / honor).",
    "L'Osmium demande 100 Seprom : vise-le seulement avec un gros stock.": "El Osmium requiere 100 Seprom: búscalo solo con mucho stock.",
