    "La Carte Stellaire permet de sauter directement vers une map débloquée.": "El mapa estelar permite saltar directamente a un mapa desbloqueado.",
    "La collecte est validée par le serveur : une box prise disparaît pour tout le monde.": "La recogida la valida el servidor: una caja recogida desaparece para todos.",
    "La dernière marche": "El último paso",
    "La fenêtre Missions liste tes quêtes actives et l'avancement de chaque objectif.": "La ventana Misiones lista tus misiones activas y el progreso de cada objetivo.",
